import{_ as h,o as t,c,a2 as a}from"./chunks/framework.62rcL0wY.js";const i="/clickermann-guide-vi/so-do/hai-che-do.svg",o="/clickermann-guide-vi/so-do/cua-so-phan-tu.svg",g="/clickermann-guide-vi/so-do/che-va-thu-nho.svg",p=JSON.parse('{"title":"Chế độ khóa cửa sổ","description":"","frontmatter":{},"headers":[],"relativePath":"khai-niem/khoa-cua-so.md","filePath":"khai-niem/khoa-cua-so.md"}'),s={name:"khai-niem/khoa-cua-so.md"};function e(r,n,l,d,m,u){return t(),c("div",null,[...n[0]||(n[0]=[a('<h1 id="che-do-khoa-cua-so" tabindex="-1">Chế độ khóa cửa sổ <a class="header-anchor" href="#che-do-khoa-cua-so" aria-label="Permalink to &quot;Chế độ khóa cửa sổ&quot;">​</a></h1><p>Trang này giải thích bản chất của <strong>chế độ khóa cửa sổ</strong> trong Clickermann, khái niệm cửa sổ và phần tử con trong Windows, cách bật và tắt khóa cửa sổ, cùng các điều kiện để đọc được màu sắc.</p><h2 id="che-do-khoa-cua-so-la-gi" tabindex="-1">Chế độ khóa cửa sổ là gì? <a class="header-anchor" href="#che-do-khoa-cua-so-la-gi" aria-label="Permalink to &quot;Chế độ khóa cửa sổ là gì?&quot;">​</a></h2><p>Ở chế độ thường, Clickermann điều khiển trực tiếp con trỏ chuột và bàn phím của máy tính (Suy luận: vì con trỏ chuột và bàn phím thật bị chiếm dụng nên trong lúc script đang chạy, bạn không thể dùng chuột hay gõ phím để làm việc khác cùng lúc).</p><p>Khi bật <strong>chế độ khóa cửa sổ</strong>, Clickermann sẽ khóa mục tiêu vào một phần tử cửa sổ cụ thể và chỉ gửi các thông điệp thao tác thẳng tới phần tử đó. Nhờ vậy, nếu ứng dụng đích cho phép nhận thông điệp ở chế độ này, <strong>cả Clickermann và bạn có thể làm việc đồng thời trên cùng một máy tính mà không hề làm phiền nhau</strong>.</p><p><img src="'+i+'" alt="So sánh chế độ thường và chế độ khóa cửa sổ"></p><h2 id="ban-chat-cua-so-va-phan-tu-con-trong-windows" tabindex="-1">Bản chất &quot;cửa sổ&quot; và &quot;phần tử con&quot; trong Windows <a class="header-anchor" href="#ban-chat-cua-so-va-phan-tu-con-trong-windows" aria-label="Permalink to &quot;Bản chất &quot;cửa sổ&quot; và &quot;phần tử con&quot; trong Windows&quot;">​</a></h2><p>Khái niệm &quot;cửa sổ&quot; của người dùng thông thường và của hệ điều hành Windows có điểm khác nhau:</p><ul><li>Với người dùng, một &quot;cửa sổ&quot; là cả khung chương trình lớn có nút đóng <code>[X]</code> ở góc phải trên.</li><li>Nhưng đối với hệ điều hành Windows, mỗi nút bấm, nhãn chữ, thanh công cụ hay ô nhập văn bản bên trong khung chương trình đó đều là một <strong>phần tử con</strong> (cửa sổ con) độc lập. Một cửa sổ ứng dụng quen thuộc có thể chứa khoảng mười phần tử con như vậy.</li><li>Mỗi phần tử đều có một mã số định danh duy nhất gọi là <strong><code>HWND</code></strong>. Khi đưa trỏ chuột lên bất kỳ vị trí nào, Clickermann sẽ hiển thị mã <code>HWND</code> của phần tử nằm ngay dưới mũi chuột tại mục &quot;Khóa cửa sổ&quot; trên màn hình chính (kèm theo mã tiến trình <code>PID</code> và tên tệp <code>.exe</code>). Ngoài ra, ngôn ngữ script còn có một số lệnh cho phép lấy mã <code>HWND</code> trong lúc script đang chạy. Suy luận: đó là các lệnh như <a href="/clickermann-guide-vi/lenh/winapi.html#wndfind"><code>WNDFIND</code></a> và <a href="/clickermann-guide-vi/lenh/winapi.html#hget"><code>HGET</code></a> trong nhóm lệnh WinAPI.</li></ul><p><img src="'+o+`" alt="Một cửa sổ ứng dụng chứa nhiều phần tử con, mỗi phần tử có HWND riêng"></p><h2 id="cach-bat-khoa-cua-so-va-he-toa-do" tabindex="-1">Cách bật khóa cửa sổ và hệ tọa độ <a class="header-anchor" href="#cach-bat-khoa-cua-so-va-he-toa-do" aria-label="Permalink to &quot;Cách bật khóa cửa sổ và hệ tọa độ&quot;">​</a></h2><p>Chế độ khóa cửa sổ được bật bằng tổ hợp phím tắt vì tại thời điểm khóa, mũi trỏ chuột của bạn cần phải đang trỏ đúng vào phần tử mục tiêu:</p><ol><li>Đưa con trỏ chuột trỏ vào <strong>phần tử mục tiêu</strong> cần tự động hóa (ví dụ khung nội dung bên trong cửa sổ ứng dụng hoặc khung Flash trong trình duyệt — bản thân khung đó cũng là một phần tử có <code>HWND</code> riêng).</li><li>Nhấn tổ hợp phím <strong><code>Alt + W</code></strong> (mặc định).</li><li>Chương trình sẽ bắt lấy phần tử dưới trỏ chuột làm <strong>phần tử đang khóa</strong>. Từ lúc này, số <code>HWND</code> trên màn hình chính sẽ đứng yên ở mã của phần tử đang khóa.</li></ol><p>Ngoài ra, bạn cũng có thể bật hoặc đổi phần tử đang khóa ngay trong code bằng lệnh <a href="/clickermann-guide-vi/lenh/winapi.html#hset"><code>HSET(hwnd, 1)</code></a>.</p><p><strong>Thay đổi về hệ tọa độ:</strong></p><ul><li>Cú pháp các lệnh trong script giữ nguyên giữa chế độ thường và chế độ khóa cửa sổ.</li><li><strong>Điểm khác biệt chính</strong> khi viết lệnh là hệ tọa độ: mỗi phần tử con có <strong>hệ tọa độ tương đối riêng</strong> với điểm <code>(0, 0)</code> nằm ở góc trái trên của chính phần tử đó. Dù bạn di chuyển cửa sổ ứng dụng sang vị trí khác trên màn hình, hệ tọa độ bên trong phần tử đang khóa vẫn không thay đổi (nếu ứng dụng cho phép hoạt động ở chế độ khóa cửa sổ).</li></ul><h2 id="tat-khoa-cua-so" tabindex="-1">Tắt khóa cửa sổ <a class="header-anchor" href="#tat-khoa-cua-so" aria-label="Permalink to &quot;Tắt khóa cửa sổ&quot;">​</a></h2><p>Trong script, để tắt chế độ khóa cửa sổ và quay về chế độ điều khiển toàn màn hình, bạn gọi thủ tục <a href="/clickermann-guide-vi/lenh/winapi.html#hset"><code>HSET(hwnd, state)</code></a> với tham số trạng thái <code>state = 0</code> (trong đó <code>hwnd</code> là mã <code>HWND</code> của phần tử, ví dụ truyền biến hệ thống <code>$_hwnd</code> của phần tử đang khóa):</p><div class="language-cms vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cms</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Tắt chế độ khóa cửa sổ bằng cách đặt state = 0</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">HSET</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">$_hwnd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">HALT</span></span></code></pre></div><p><em>(Lưu ý: nếu chỉ muốn đổi sang khóa một phần tử khác, bạn gọi thẳng <code>HSET(hwnd_moi, 1)</code> mà không cần tắt trước bằng cờ <code>0</code>. Việc gọi <code>HSET(0, 0)</code> với <code>hwnd = 0</code> hoặc nhấn lại phím tắt <code>Alt + W</code> lần thứ hai có tắt được khóa cửa sổ hay không được ghi nhận tại <a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html#cach-tat-che-do-khoa-cua-so">Cần kiểm tra trên Windows</a>).</em></p><h2 id="khi-nao-doc-duoc-mau-o-che-do-khoa-cua-so" tabindex="-1">Khi nào đọc được màu ở chế độ khóa cửa sổ? <a class="header-anchor" href="#khi-nao-doc-duoc-mau-o-che-do-khoa-cua-so" aria-label="Permalink to &quot;Khi nào đọc được màu ở chế độ khóa cửa sổ?&quot;">​</a></h2><p>Các lệnh phân tích màn hình (như <a href="/clickermann-guide-vi/lenh/man-hinh.html#getscreen"><code>GETSCREEN</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-pixel-in-end-if"><code>IF_PIXEL_IN</code></a>, <a href="/clickermann-guide-vi/lenh/man-hinh.html#if-picture-in-end-if"><code>IF_PICTURE_IN</code></a>) ở chế độ khóa cửa sổ tuân theo quy tắc sau:</p><ul><li><strong>Cửa sổ bị che khuất bởi cửa sổ khác:</strong> <strong>Có thể đọc được màu, tùy ứng dụng; hãy kiểm tra bằng kính lúp</strong>. Trong một số trường hợp, bạn có thể mở cửa sổ Word hoặc xem phim đè lên trên cửa sổ đang khóa mà script vẫn phân tích được đồ họa.</li><li><strong>Cửa sổ bị thu nhỏ xuống thanh tác vụ (Minimize):</strong> <strong>Không đọc được màu</strong>. Lý do là khi cửa sổ bị thu nhỏ xuống thanh tác vụ, Windows ngừng vẽ đồ họa của cửa sổ đó để tiết kiệm tài nguyên hệ thống.</li></ul><p><img src="`+g+'" alt="So sánh cửa sổ bị che khuất và cửa sổ bị thu nhỏ"></p><p><strong>Cách kiểm tra nhanh:</strong> Sau khi bật khóa cửa sổ, hãy mở <a href="/clickermann-guide-vi/bat-dau/trinh-soan-thao.html">Trình soạn thảo</a> và bật <strong>kính lúp</strong>. Nếu màu sắc/hình ảnh trong kính lúp vẫn thay đổi ngay cả khi có cửa sổ khác đè lên thì mọi thứ hoạt động tốt; ngược lại nếu kính lúp luôn chỉ có màu đen thì không phân tích hình ảnh ở chế độ khóa cửa sổ được. <em>(Hãy nhớ <strong>tắt kính lúp</strong> sau khi kiểm tra xong nếu thấy con trỏ chuột di chuyển chậm).</em></p><h2 id="gioi-han-va-giai-phap-dung-may-ao" tabindex="-1">Giới hạn và giải pháp dùng máy ảo <a class="header-anchor" href="#gioi-han-va-giai-phap-dung-may-ao" aria-label="Permalink to &quot;Giới hạn và giải pháp dùng máy ảo&quot;">​</a></h2><ul><li>Không phải ứng dụng nào cũng cho phép hoạt động ở chế độ khóa cửa sổ; khả năng hoạt động phụ thuộc vào cách ứng dụng đích được viết. Lệnh <a href="/clickermann-guide-vi/lenh/chuot.html#mover"><code>MOVER</code></a> cũng không hoạt động ở chế độ khóa cửa sổ.</li><li>🟠 <strong>Lưu ý về trình duyệt web và máy ảo:</strong><ul><li><strong>Nên làm:</strong> Với trình duyệt web, hãy trỏ chuột vào đúng phần tử nội dung bên trong trang rồi nhấn <code>Alt + W</code> và bật kính lúp kiểm tra thử (thử đổi trình duyệt khác như Firefox nếu Chrome không nhận). Nếu ứng dụng hoàn toàn không nhận chế độ khóa cửa sổ, bạn có thể cài cả Windows, ứng dụng và Clickermann vào <strong>bên trong máy ảo</strong> rồi chạy ở chế độ thường trong máy ảo đó.</li></ul><details class="details custom-block"><summary>Vì sao chưa chắc</summary><ul><li><strong>Theo sách của Chô tô (tr. 19):</strong> Xếp chung trình duyệt và máy ảo vào nhóm cửa sổ không nhận Clickermann ở chế độ khóa cửa sổ.</li><li><strong>Theo help (bài Khóa cửa sổ và phần FAQ):</strong> Giải thích rằng khả năng hoạt động ở chế độ khóa cửa sổ <strong>tùy cách ứng dụng được viết</strong> (ví dụ khung Flash trong trình duyệt là một phần tử con riêng, hoặc có trường hợp chạy được trên Firefox nhưng không chạy trên Google Chrome).</li><li><strong>Giải pháp dùng máy ảo (theo help, bài Khóa cửa sổ):</strong> Với máy ảo (như MS Virtual PC, VMware), help gợi ý đây là <strong>giải pháp thay thế</strong> khi chế độ khóa cửa sổ không dùng được: bạn cài hệ điều hành, ứng dụng và Clickermann <strong>vào bên trong máy ảo</strong>, cho chạy ở chế độ thường bên trong máy ảo rồi thu nhỏ cửa sổ máy ảo xuống để làm việc khác trên máy thật. Tuy nhiên, help lưu ý cách này đòi hỏi máy tính đủ mạnh để gánh hai hệ điều hành cùng ứng dụng, và một số ứng dụng chạy khá kém hoặc từ chối chạy trên máy ảo. Xem thêm tại <a href="/clickermann-guide-vi/phu-luc/can-kiem-tra-tren-windows.html#che-do-khoa-cua-so-voi-trinh-duyet-va-may-ao">Cần kiểm tra trên Windows</a>.</li></ul></details></li><li><strong>Điều khiển nhiều cửa sổ cùng lúc bằng thư viện cộng đồng:</strong> Khi một script cần gửi thao tác chuột và phím tới nhiều cửa sổ khác nhau mà không muốn gọi <code>HSET</code> chuyển đổi mục tiêu liên tục, bạn có thể tham khảo thêm <a href="/clickermann-guide-vi/nang-cao/alt-winmode.html">Thư viện alt_winmode</a> trong nhóm Nâng cao.</li></ul><hr><p><em>Nguồn: Tài liệu trợ giúp <code>help.chm</code> (bài Khóa cửa sổ, mục WinAPI và khóa cửa sổ, mục Chuột và phần FAQ); tham khảo đối chiếu sách của Chô tô (tr. 19).</em></p>',29)])])}const v=h(s,[["render",e]]);export{p as __pageData,v as default};
